(60, NULL, 'Vape Accessories', 'vape-accessories', '/vape-accessories', NULL, 'Shop essential vape hardware, accessories, batteries and pods.', '<h2 style=\"margin-top: 20pt; margin-bottom: 6pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Vape Accessories: The Small Upgrades That Make a Big Difference&nbsp;</span></h2><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">The quality of your vaping experience depends on the individual components of your </span><span style=\"text-decoration: underline; font-weight: 400; font-variant: normal; text-decoration-skip-ink: none; vertical-align: baseline; white-space: pre-wrap;\"><a href=\"https://infinityvapeshop.com/disposable-vapes\">disposable vape</a></span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">. New pods, power supplies, and other accessories can help ensure smooth operation. For anyone looking to meet their device’s needs, our collection of vape accessories is a must-see.</span></p><br><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Regardless of the type of device you own, whether it’s a vape pen, a pod system, or a more advanced model, the right accessories can help you enhance your vaping experience without any hassle. Here is a quick look at what matters most:</span></p><br><div dir=\"ltr\" style=\"margin-left:0pt;\" align=\"left\"><table style=\"border:none;border-collapse:collapse;\"><colgroup><col width=\"175\"><col width=\"211\"><col width=\"214\"></colgroup><tbody><tr style=\"height:0pt\"><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-weight: 700; font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Accessory</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-weight: 700; font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">What It Does</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-weight: 700; font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Examples You Can Explore</span></p></td></tr><tr style=\"height:0pt\"><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Vape pods</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">They hold the e-liquid and give you fresh flavor in seconds</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Foger Switch Pro Refill Pods, JUUL Pods, Blu Liquid Pods, RAZ RYL Vue Pods</span></p></td></tr><tr style=\"height:0pt\"><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Vape batteries</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Power your device so it is ready to use</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Foger Switch Pro Battery (1200mAh), Cookies Twist 510 Thread Battery (900mAh)</span></p></td></tr><tr style=\"height:0pt\"><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Vape mod batteries</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Supply steady power to box mods and larger setups</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Box mod battery options in our accessories range</span></p></td></tr><tr style=\"height:23.89892578125pt\"><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Vape coils</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Heat the liquid to make vapor</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Match to your device, tank, or pod</span></p></td></tr><tr style=\"height:0pt\"><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Vape tanks</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Hold the liquid and house the coil in refillable setups</span></p></td><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Match to your device and mod</span></p></td></tr></tbody></table></div><h2 dir=\"ltr\" style=\"margin-top: 18pt; margin-bottom: 6pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Vape Pods and Batteries: The Heart of Your Setup&nbsp;</span></h2><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Let us take a look at the most frequently used accessories. </span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\" class=\"\">Vape pods</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> are the most effective way to upgrade any device; simply snap one in and get going. Among our offerings, you will come across various options, including Foger Switch Pro Refill Pods. Its 30K pod with 19 mL capacity allows you to have a satisfying vaping experience. POD choices like JUUL Pods in flavors like Virginia Tobacco and Menthol, and Blu Liquid Pods, consisting of two 1.5 mL pre-filled pods, are available at various strengths. RAZ has brought RYL Vue 70K pods available in a size of 16 mL that are offered in 10 flavored e-liquids.</span></p><br><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">It is important to ensure that the pod you are selecting is meant for your device. Pods are produced specifically for certain vapor systems, so a JUUL pod will not fit in Foger and vice versa. Thus, you can save your time and money by checking the product page beforehand.</span></p><br><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">The quality of </span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\" class=\"\">vape batteries</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> is important in keeping your device charged. A good vape battery provides a good power source that helps you avoid running out of power during vaping sessions. For instance, the Foger Switch Pro Battery has a capacity of 1200 mAh and pairs well with the Switch Pro pod device. If you use cartridges that have 510 threads, the Cookies Twist 510 Thread Battery will also do a great job with a capacity of 900 mAh.</span></p><br><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">When looking for the </span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\" class=\"\">best vape batteries</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">, consider two things. First, check for compatibility. Second, always check for capacity measured in mAh, since larger capacities need less frequent charging.</span></p><h2 dir=\"ltr\" style=\"margin-top: 18pt; margin-bottom: 6pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Vape Mod Batteries: Steady Power for Bigger Setups&nbsp;</span></h2><p dir=\"ltr\" style=\"margin-top: 12pt; margin-bottom: 12pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Bigger devices need a stronger, steadier power source, and that’s where mod batteries come in. You’ll find everything you need in the </span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\" class=\"\">vape mod batteries</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> category in the accessories section of our store.</span></p><p dir=\"ltr\" style=\"margin-top: 12pt; margin-bottom: 12pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">A few safety tips to keep in mind:</span></p><ul style=\"margin-bottom: 0px; padding-inline-start: 48px;\"><li dir=\"ltr\" style=\"list-style-type: disc; font-variant: normal; vertical-align: baseline; white-space: pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"margin-top: 12pt; margin-bottom: 0pt;\" role=\"presentation\"><span style=\"font-weight: 700; font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Match your batteries to your device.</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> Only use ones that are compatible with it.</span></p></li><li dir=\"ltr\" style=\"list-style-type: disc; font-variant: normal; vertical-align: baseline; white-space: pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\" role=\"presentation\"><span style=\"font-weight: 700; font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Don’t mix old and new.</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> Always use batteries from the same set.</span></p></li><li dir=\"ltr\" style=\"list-style-type: disc; font-variant: normal; vertical-align: baseline; white-space: pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\" role=\"presentation\"><span style=\"font-weight: 700; font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Store them safely.</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> Keep them in a battery case, away from keys, coins, and other metal objects.</span></p></li><li dir=\"ltr\" style=\"list-style-type: disc; font-variant: normal; vertical-align: baseline; white-space: pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\" role=\"presentation\"><span style=\"font-weight: 700; font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Use the right charger.</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> Use the one made for your batteries.</span></p></li><li dir=\"ltr\" style=\"list-style-type: disc; font-variant: normal; vertical-align: baseline; white-space: pre;\" aria-level=\"1\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 12pt;\" role=\"presentation\"><span style=\"font-weight: 700; font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Replace damaged batteries.</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> If you see any wear, tears, or dents, swap them out right away.</span></p></li></ul><h2 dir=\"ltr\" style=\"margin-top: 18pt; margin-bottom: 6pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Best Vape Accessories: Coils, Tanks, and Mod Extras</span></h2><p dir=\"ltr\" style=\"margin-top: 12pt; margin-bottom: 12pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Beyond pods and power: a few parts make a big difference to your flavor and vapor. </span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\" class=\"\">Vape coils</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> are the small heating elements that turn e-liquid into vapor. They wear out over time, and when your vape starts tasting burnt or flat, a fresh coil is the quickest way to get the flavor back. </span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\" class=\"\">Vape Tanks</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> hold your e-liquid and house the coil, and they come in different sizes and airflow styles. Choose one that fits how you like to vape, whether that\'s a tight, snug draw or a bigger, cloud-friendly pull.</span></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Together, these parts make up the heart of your</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\" class=\"\"> vape mod accessories</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">. If you use a refillable mod, you will want a spare coil on hand, a tank that fits your style, and a battery you can trust. If you prefer a pod device, keep a couple of spare pods and a charged battery ready.</span></p><br><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Are you eager to improve your setup? </span><span style=\"text-decoration: underline; font-weight: 400; font-variant: normal; text-decoration-skip-ink: none; vertical-align: baseline; white-space: pre-wrap;\"><a href=\"https://infinityvapeshop.com/\">Infinity Vape Shop</a></span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> is a renowned and reliable online vape supplier. The store provides different options for users, making the shopping process easy, smooth, and convenient. Whether you want vape pods, batteries, vape mod batteries, or the best accessories for your device, Infinity Vape Shop will help you find the right options.</span></p><br><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">To keep your device powered, browse our collection of </span><span style=\"text-decoration: underline; font-weight: 400; font-variant: normal; text-decoration-skip-ink: none; vertical-align: baseline; white-space: pre-wrap;\"><a href=\"https://infinityvapeshop.com/vape-accessories/batteries\">vape batteries</a></span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"><a href=\"https://infinityvapeshop.com/vape-accessories/batteries\"> </a>and explore the available options.</span></p><div><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"><br></span></div>', NULL, NULL, 'Vape Accessories - Infinity Vape Shop', 'Find the best vape accessories at Infinity Vape Shop. Explore essential vaping gear and shop our collection today to find accessories for your setup!', 0, 1),
(61, 60, 'Batteries', 'batteries', '/vape-accessories/batteries', NULL, 'High performance box mod batteries and power cells.', '<h1 dir=\"ltr\" style=\"margin-top: 20pt; margin-bottom: 6pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Vape Batteries: Power Up Without Missing a Beat&nbsp;</span></h1><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">A dead battery ruins a good vaping session. The good news is that a good </span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\" class=\"\">vape battery</span><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\"> solves this problem. Whether you vape at home, at work, or on the go, the right power source keeps your device ready when you are.</span></p><br><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Our battery collection allows you to find appropriate devices for your needs. You will find batteries for box mods, pen-style devices, and modular pod systems, so there is something for every setup.</span></p><br><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-variant: normal; vertical-align: baseline; white-space: pre-wrap;\">Here is a quick overview:</span></p><br><div dir=\"ltr\" style=\"margin-left:0pt;\" align=\"left\"><table style=\"border:none;border-collapse:collapse;\"><colgroup><col width=\"182\"><col width=\"184\"><col width=\"205\"></colgroup><tbody><tr style=\"height:0pt\"><td style=\"border-left:solid #000000 1pt;border-right:solid #000000 1pt;border-bottom:solid #000000 1pt;border-top:solid #000000 1pt;vertical-align:top;padding:5pt 5pt 5pt 5pt;overflow:hidden;overflow-wrap:break-word;\"><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt;\"><span style=\"font-