INSERT INTO `pages` (`id`, `title`, `slug`, `custom_url_path`, `content`, `meta_title`, `meta_desc`, `schema_markup`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'About Us', 'about-us', '/page/about-us', '<h2>Welcome to New Vape</h2><p>New Vape is dedicated to providing adult vapor consumers with authentic, certified, and compliant vaping hardware and e-liquids at competitive prices.</p>', 'About New Vape | Our Story & Mission', 'Learn about New Vape, our commitment to adult age verification, and our authentic product catalog.', NULL, 1, '2026-10-16 18:29:29', '2026-10-29 21:14:48'),
(2, 'Contact Us', 'contact-us', '/page/contact-us', '<h2>Get in Touch</h2><p>Have questions about your order or product compatibility? Our friendly customer support team is available 7 days a week.</p>', 'Contact New Vape Support', 'Reach out to our customer service team via email, phone, or live chat.', NULL, 1, '2026-10-16 18:29:29', '2026-10-29 21:14:48'),
(3, 'Privacy Policy', 'privacy-policy', '/page/privacy-policy', '<h2>Privacy Policy</h2><p>Your privacy is important to us. This policy details how we collect, store, and protect your personal identification data.</p>', 'Privacy Policy | New Vape', 'Official privacy policy of New Vape.', NULL, 1, '2026-10-16 18:29:29', '2026-10-29 21:14:48'),
(4, 'Terms & Conditions', 'terms-and-conditions', '/page/terms-and-conditions', '<h2>Terms of Service</h2><p>By accessing or purchasing from New Vape, you certify that you are at least 21 years of age.</p>', 'Terms of Service | New Vape', 'General terms and conditions for shopping at New Vape.', NULL, 1, '2026-10-16 18:29:29', '2026-11-02 16:24:24'),
(5, 'Shipping Policy', 'shipping-policy', '/page/shipping-policy', '<h2>Shipping & PACT Act Compliance</h2><p>All vape orders are shipped via adult signature delivery (21+) in accordance with the federal PACT Act.</p>', 'Shipping & Return Policy | New Vape', 'Information regarding delivery times, adult signature requirements, and returns.', NULL, 1, '2026-10-16 18:29:29', '2026-10-29 21:14:48'),
(6, 'FDA Disclaimer', 'fda-disclaimer', '/page/fda-disclaimer', '<h2>Age Verification (21+)</h2><p>Federal law prohibits the sale of nicotine products to anyone under the age of 21. We employ third-party age verification at checkout.</p>', 'Age Verification 21+ | New Vape', 'Details regarding our mandatory 21+ age verification policy.', NULL, 1, '2026-10-16 18:29:29', '2026-10-29 21:14:48'),
(7, 'Refund Policy', 'refund-policy', '/page/refund-policy', NULL, 'Refund & Return Policy | Vape City USA', 'Official refund and return guidelines for Vape City USA products.', NULL, 1, '2026-10-29 21:14:48', '2026-10-29 21:14:48'),
(8, 'FAQs', 'faqs', '/page/faqs', NULL, 'Frequently Asked Questions | New Vape', 'Common questions about shipping, 21+ age verification, and orders.', NULL, 1, '2026-10-29 21:14:48', '2026-11-02 18:09:43'),
(9, 'Track Your Order', 'track-order', '/page/track-order', NULL, 'Track Your Order | New Vape', 'Look up your package tracking status in real time.', NULL, 1, '2026-10-29 21:14:48', '2026-10-29 21:14:48');

