INSERT INTO `products` (`id`, `brand_id`, `name`, `title`, `sku`, `slug`, `custom_url`, `short_desc`, `long_desc`, `related_posts_content`, `base_price`, `compare_price`, `stock_quantity`, `stock_status`, `featured_image`, `rating_avg`, `reviews_count`, `bundle_banner_active`, `bundle_banner_img`, `bundle_banner_link`, `status`, `is_new`, `is_bestseller`, `is_featured`, `tags`, `option_names`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES
(1, 1, 'Lost Mary MT35000 Turbo Vape - 35,000 Puffs, 37 Flavors, Hidden Display', 'Lost Mary MT35000 Turbo Vape - 35,000 Puffs, 37 Flavors, Hidden Display', 'LM-MT35000-35K-DV', 'lost-mary-mt35000-turbo-vape', 'lost-mary-mt35000-turbo-vape', 'The <strong>Lost Mary MT35000 Turbo</strong> is a 35,000 puff disposable vape with 18ml of 5% nicotine salt, dual mesh coils and a 1000mAh battery. A hidden display shows battery mode and e-liquid when you draw. 37 flavors in stock.', 'The Lost Mary MT35000 Turbo is a rechargeable disposable vape rated for 35,000 puffs in Smooth Mode and about 20,000 in Turbo Mode. It carries 18mL of 5% nicotine salt, dual mesh coils, a 1,000mAh battery and a display that stays hidden until you draw. With 37 flavors in stock at New Vape, it has the widest menu of any 35K device we sell.', NULL, 18.49, 29.50, 1348, 'In Stock', 'assets/images/vape-image.webp', 5.00, 3, 0, 'assets/images/limited-time.webp', NULL, 'published', 0, 0, 0, 'Disposable, 35000 Puffs, Rechargeable, Dual Mesh, Lost Mary, Best Seller', '[\"Flavor\"]', 'Lost Mary MT35000 Turbo Disposable Vape | 35K Puffs | New Vape', 'Shop Lost Mary MT35000 Turbo with 35,000 puffs, dual mesh coil, 1000mAh rechargeable battery, and 37 flavors in stock.', '2026-10-16 18:29:22', '2026-11-03 21:07:42'),
(2, 2, 'Geek Bar Pulse 15K Disposable', 'Geek Bar Pulse 15K Disposable', 'VH-GB-15K', 'geek-bar-pulse-15k-disposable', 'geek-bar-pulse-15k-disposable', 'The legendary full-screen pulse mode disposable with dual core technology, cosmic animations, and 15,000 puffs.', 'Full screen display with rocket animations, 15,000 regular puffs or 7,500 pulse puffs. Dual mesh coils for unmatched flavor punch.', NULL, 14.99, 22.99, 115, 'In Stock', 'assets/images/most-popular-1.webp', 5.00, 1, 0, 'assets/images/limited-time.webp', NULL, 'published', 0, 0, 0, 'Disposable, Geek Bar, Pulse, 15000 Puffs', '[\"Flavor\"]', 'Geek Bar Pulse 15000 Disposable Vape | New Vape', 'Buy Geek Bar Pulse 15K with dual mesh coils and dual power modes.', '2026-10-16 18:29:22', '2026-11-03 20:57:58'),
(3, 2, 'GB Pulse 2 25K Disposable', 'GB Pulse 2 25K Disposable', 'VH-GB-25K', 'gb-pulse-2-25k-disposable', 'gb-pulse-2-25k-disposable', 'Next-generation Pulse 2 featuring curved 3D screen, 25,000 puffs, and dynamic airflow adjustment.', 'Next gen 25K capacity with 3D wrap-around digital screen, airflow switch, and dual power modes.', NULL, 17.99, 26.99, 45, 'In Stock', 'assets/images/most-popular-2.webp', 0.00, 0, 0, 'assets/images/limited-time.webp', NULL, 'published', 0, 0, 0, 'Disposable, Geek Bar, 25000 Puffs, New Arrival', '[\"Flavor\"]', 'Geek Bar Pulse 2 25K Disposable | New Vape', 'The latest Geek Bar Pulse 2 25,000 puff disposable device.', '2026-10-16 18:29:22', '2026-11-03 20:57:58'),
(4, 5, 'Voopoo Drag S2 Pod Kit', 'Voopoo Drag S2 Pod Kit', 'VH-VP-DS2', 'voopoo-drag-s2-pod-kit', 'voopoo-drag-s2-pod-kit', 'High-performance 60W internal battery pod mod kit featuring Gene.TT 2.0 chipset and PnP X leak-proof platform.', 'Features top airflow intake, leak-proof design, and 4-layer silicone seals for clean and intense flavor delivery.', NULL, 39.99, 54.99, 18, 'In Stock', 'assets/images/most-popular-3.webp', 5.00, 1, 0, 'assets/images/limited-time.webp', NULL, 'published', 0, 0, 0, 'Pod Mod, Starter Kit, Voopoo, 60W, Refillable', '[\"Color\"]', 'Voopoo Drag S2 60W Pod Kit | New Vape', 'Buy authentic Voopoo Drag S2 60W pod system with internal 2500mAh battery.', '2026-10-16 18:29:22', '2026-11-03 20:57:58'),
(5, 6, 'Vaporesso Luxe Q2 SE Kit', 'Vaporesso Luxe Q2 SE Kit', 'VH-VP-LQ2', 'vaporesso-luxe-q2-se-kit', 'vaporesso-luxe-q2-se-kit', 'Sleek, pocket-sized pod system with AXON chip, 1000mAh battery, and SSS leak-resistant technology.', 'Built-in 1000mAh high-density battery supporting 48 hours of uninterrupted vaping. Corex heating tech for pure flavor.', NULL, 21.99, 31.99, 32, 'In Stock', 'assets/images/product-5.webp', 0.00, 0, 0, 'assets/images/limited-time.webp', NULL, 'published', 0, 0, 0, 'Pod Kit, Vaporesso, Luxe Q2, MTL, Refillable', '[\"Color\"]', 'Vaporesso Luxe Q2 SE Pod System | New Vape', 'Order Vaporesso Luxe Q2 SE kit with 1000mAh battery and Corex mesh pods.', '2026-10-16 18:29:22', '2026-11-03 20:57:58'),
(6, 4, 'Juice Head Salt x Vaporesso 50K Bundle – Device + Juice 30mL', 'Juice Head Salt x Vaporesso 50K Bundle – Device + Juice 30mL', 'VH-JH-50K', 'juice-head-salt-vaporesso-50k-bundle', 'juice-head-salt-vaporesso-50k-bundle', 'Exclusive bundle: Vaporesso hardware paired with Juice Head premium salt nicotine e-liquid (30mL).', 'Get the ultimate smooth nicotine hit with our bundle featuring Vaporesso pod hardware and 30ml Juice Head Salt.', NULL, 29.99, 44.99, 85, 'In Stock', 'assets/images/flavor-guava-peach.png', 0.00, 0, 0, 'assets/images/limited-time.webp', NULL, 'published', 0, 0, 0, 'Bundle Deal, E-Liquid, Pod Hardware, Juice Head, Salt Nic', '[\"Flavor Option\",\"Nicotine Strength\"]', 'Juice Head Salt x Hardware 50K Bundle | New Vape', 'Save big on Juice Head Salt 30ml paired with high-performance refillable device.', '2026-10-16 18:29:22', '2026-11-03 20:57:58'),
