INSERT INTO `product_faqs` (`id`, `product_id`, `question`, `answer`, `sort_order`) VALUES
(1, 1, 'What is the RYL vape?', 'The RYL vape (by RAZ) is an advanced high-puff rechargeable disposable device delivering up to 35,000 puffs. It features dual mesh coils, a sleek body design, an active digital display, and a curated lineup of premium fruit, icy, and sweet candy flavors.', 1),
(2, 1, 'How many puffs does the RAZ RYL 35K last?', 'The device is rated for up to 35,000 puffs in Regular/Smooth Mode. In Turbo Mode with higher vapor density and power output, expect around 20,000 puffs. For typical daily vapers, a single device lasts 4 to 8 weeks.', 2),
(3, 1, 'Does the RYL come with the chain?', 'Yes! Selected editions of the RYL 35K kit package include a metallic chain lanyard strap that attaches to the device corner, making it convenient and stylish to carry.', 3),
(4, 1, 'What is the difference between Classic, Spring and Winter Edition?', 'The differences are visual aesthetics and seasonal flavor recipes. Classic provides popular all-day essentials, Spring Edition offers vibrant floral-fruity combinations, and Winter Edition brings cooler frost and mint profiles.', 4),
(5, 1, 'How much nicotine is in the RYL 35K?', 'The RYL 35K comes prefilled with 5% (50mg/mL) nicotine salt e-liquid, engineered for smooth throat satisfaction and fast absorption.', 5),
(6, 1, 'Does the RYL have adjustable airflow?', 'Yes, an intuitive airflow slider switch on the bottom allows vapers to fine-tune the draw between a tight mouth-to-lung (MTL) draw and an open restricted direct-to-lung (RDL) hit.', 6),
(7, 1, 'How do you charge the RYL 35K?', 'Connect any Type-C USB cable to the bottom charging port. It takes around 60 to 90 minutes to fully charge. Avoid using fast charging laptop bricks to prolong internal battery longevity.', 7),
(28, 52, 'How many puffs does the test actually deliver?', 'The test is engineered to deliver up to its rated puffs depending on draw length and frequency. Standard moderate vaping typically lasts 2 to 4 weeks per device.', 1),
(212, 59, 'FAQ #1', 'FAQ #1', 1),
(213, 59, 'FAQ #2', 'FAQ #2', 2),
(214, 59, 'FAQ #3', 'FAQ #3', 3),
(215, 59, 'FAQ #4', 'FAQ #4', 4);

